<script setup lang="ts">
import {computed,ref} from 'vue'
import {ArrowLeft,ArrowRight,Bike,Check,Clock3,Download,Footprints,Heart,Mountain,Navigation,Pencil,Plus,Route,Search,Trash2,Upload} from '@lucide/vue'
import TravelModal from './TravelModal.vue'
import RouteFields from './RouteFields.vue'
import TravelMap from './TravelMap.vue'
import {emptyRoute,saveRoute,removeRoute,routeModes,routeShapes,difficulties,routeInput,validateRoute,type SavedRoute,type SavedRouteInput} from './library'
import {daysBetween,download,hasCoordinates,safeSource} from './model'
import {apiRequest} from '../api/client'
import {useTripsStore} from '../stores/trips'
import type {TripRecord} from '../api/trips'
import type {Place} from '../stores/places'
const props=defineProps<{routes:SavedRoute[];places:Place[];loadError:string}>()
const emit=defineEmits<{changed:[];import:[];openTrip:[trip:TripRecord];openPlaces:[];reload:[]}>()
const trips=useTripsStore(),query=ref(''),filter=ref('all'),selection=ref(''),editor=ref<SavedRouteInput|null>(null),editingId=ref<string>(),busy=ref(false),error=ref(''),applyOpen=ref(false),deleteOpen=ref(false),tripId=ref(''),date=ref(''),startsAt=ref('09:00'),minutes=ref(30)
const selected=computed(()=>props.routes.find(r=>r.id===selection.value)||null)
const list=computed(()=>props.routes.filter(r=>(filter.value==='all'||r.mode===filter.value||(filter.value==='favorites'&&r.favorite))&&`${r.name} ${r.city} ${r.tags.join(' ')} ${r.waypoints.map(p=>p.name).join(' ')}`.toLowerCase().includes(query.value.toLowerCase().trim())))
const targetTrip=computed(()=>trips.trips.find(t=>t.id===tripId.value)),dates=computed(()=>daysBetween(targetTrip.value?.startsOn||null,targetTrip.value?.endsOn||null))
const mapPoints=computed(()=>selected.value?.waypoints.flatMap((w,index)=>{const matches=props.places.filter(p=>p.name===w.name&&p.city===selected.value?.city&&hasCoordinates(p));return matches.length===1?[{...matches[0]!,id:String(index),name:w.name,order:index+1}]:[]})||[])
function edit(route?:SavedRoute){editingId.value=route?.id;editor.value=route?copy(route):emptyRoute();error.value=''}
// JSON cloning accepts Vue proxies and Safari versions that cannot clone them.
function copy(value:SavedRouteInput){return JSON.parse(JSON.stringify(routeInput(value))) as SavedRouteInput}
async function persist(){if(!editor.value||busy.value)return;error.value=validateRoute(editor.value);if(error.value)return;busy.value=true;try{const saved=await saveRoute(copy(editor.value),editingId.value);selection.value=saved.id;editor.value=null;emit('changed')}catch(cause){error.value=cause instanceof Error?cause.message:'保存失败'}finally{busy.value=false}}
async function toggle(key:'favorite'|'completed'){if(!selected.value||busy.value)return;busy.value=true;error.value='';try{await saveRoute({...copy(selected.value),[key]:!selected.value[key]},selected.value.id);emit('changed')}catch(cause){error.value=cause instanceof Error?cause.message:'保存失败'}finally{busy.value=false}}
async function destroy(){if(!selected.value||busy.value)return;busy.value=true;error.value='';try{await removeRoute(selected.value.id);selection.value='';deleteOpen.value=false;emit('changed')}catch(cause){error.value=cause instanceof Error?cause.message:'删除失败'}finally{busy.value=false}}
function startApply(){error.value='';tripId.value='';date.value='';applyOpen.value=true}
function chooseTrip(){date.value=dates.value[0]||''}
async function apply(){if(!selected.value||busy.value||!tripId.value||!date.value)return;busy.value=true;error.value='';try{const trip=await apiRequest<TripRecord>('/api/v1/library/routes/'+selected.value.id+'/apply',{method:'POST',body:JSON.stringify({tripId:tripId.value,date:date.value,startsAt:startsAt.value,minutesPerStop:minutes.value})});const index=trips.trips.findIndex(t=>t.id===trip.id);if(index>=0)trips.trips[index]=trip;trips.persist();applyOpen.value=false;emit('openTrip',trip)}catch(cause){error.value=cause instanceof Error?cause.message:'添加失败'}finally{busy.value=false}}
function exportSelected(){if(selected.value)download(selected.value.name+'-路线.json',JSON.stringify({type:'wheretogo.route',version:1,route:routeInput(selected.value)},null,2),'application/json')}
</script>
<template>
  <section class="tw-route-library"><header class="tw-section-heading tw-page-heading"><div><span class="tw-kicker">TAKE THE SCENIC ROUTE</span><h1>收下一段，想走的路。</h1><p>徒步、骑行与城市漫步，留待下一次出发。</p></div><div class="tw-heading-actions"><button class="tw-button secondary" @click="emit('import')"><Upload :size="15"/>从资料导入</button><button class="tw-button primary" @click="edit()"><Plus :size="15"/>收藏路线</button></div></header>
    <div v-if="loadError" class="tw-page-error" role="alert">{{ loadError }}<button @click="emit('reload')">重新加载</button></div><p v-if="error&&!editor&&!applyOpen&&!deleteOpen" class="tw-page-error" role="alert">{{ error }}</p>
    <template v-if="!selected"><div class="tw-route-filter"><div class="tw-tabs" role="group" aria-label="路线类型"><button v-for="tab in [{key:'all',label:'所有路线'},...Object.entries(routeModes).map(([key,label])=>({key,label})),{key:'favorites',label:'特别想走'}]" :key="tab.key" :class="{active:filter===tab.key}" @click="filter=tab.key">{{ tab.label }}</button></div><label class="tw-search"><Search :size="16"/><input v-model="query" placeholder="路线、城市或途经点" aria-label="搜索收藏路线"/></label></div>
      <div class="tw-route-grid"><article v-for="route in list" :key="route.id" class="tw-route-card"><button @click="selection=route.id;error='' "><div class="tw-route-cover" :class="'tw-route-'+route.mode"><Bike v-if="route.mode==='cycling'" :size="35"/><Footprints v-else-if="route.mode==='hiking'" :size="35"/><Navigation v-else :size="35"/><span>{{ routeModes[route.mode] }}<small>{{ route.completed?'已经走过':'留给下一次出发' }}</small></span><Heart v-if="route.favorite" :size="17" fill="currentColor"/></div><div class="tw-route-card-body"><small>{{ route.city }} · {{ routeShapes[route.shape] }}</small><h3>{{ route.name }}</h3><p>{{ route.waypoints[0]?.name }}<ArrowRight :size="12"/>{{ route.waypoints.at(-1)?.name }}</p><div class="tw-route-metrics"><span><Route :size="14"/>{{ route.distanceKm!=null?route.distanceKm+' km':'里程待确认' }}</span><span><Clock3 :size="14"/>{{ route.durationMinutes!=null?route.durationMinutes+' 分钟':'耗时待确认' }}</span><span><Mountain :size="14"/>{{ route.ascentM!=null?route.ascentM+' m':'爬升待确认' }}</span></div><footer><span>{{ route.waypoints.length }} 个途经点 · {{ difficulties[route.difficulty] }}</span><ArrowRight :size="16"/></footer></div></button></article></div>
      <div v-if="!list.length" class="tw-empty tw-route-empty"><Route :size="34"/><h3>把想走的路线，先收好。</h3><p>上传游记截图或路线攻略，提取有顺序的途经点；<br/>也可以手动记录一条自己的经典路线。</p><button class="tw-button primary" @click="emit('import')"><Plus :size="15"/>导入第一条路线</button></div>
    </template>
    <template v-else><button class="tw-text tw-route-back" @click="selection='';error='' "><ArrowLeft :size="15"/>返回路线收藏</button><section class="tw-route-detail"><div class="tw-route-story"><span class="tw-kicker">{{ routeModes[selected.mode] }} · {{ selected.city }}</span><h2>{{ selected.name }}</h2><p>{{ selected.description||'还没有路线介绍，可以编辑补充亮点和沿途风景。' }}</p><div class="tw-route-detail-metrics"><span><b>{{ selected.distanceKm??'—' }}</b><small>公里 · 资料标注</small></span><span><b>{{ selected.durationMinutes??'—' }}</b><small>分钟 · 资料标注</small></span><span><b>{{ selected.ascentM??'—' }}</b><small>米爬升 · 资料标注</small></span></div><div class="tw-place-tags"><span>{{ routeShapes[selected.shape] }}</span><span>{{ difficulties[selected.difficulty] }}</span><span>{{ selected.waypoints.length }} 站</span><span>{{ selected.completed?'已走过':'待出发' }}</span></div><div class="tw-route-detail-actions"><button class="tw-button primary" @click="startApply"><Plus :size="15"/>加入旅行</button><button class="tw-button secondary" @click="edit(selected)"><Pencil :size="14"/>编辑</button><button class="tw-icon" :disabled="busy" :aria-label="selected.favorite?'取消特别想走':'特别想走'" @click="toggle('favorite')"><Heart :size="17" :fill="selected.favorite?'currentColor':'none'"/></button><button class="tw-button secondary" :disabled="busy" @click="toggle('completed')"><Check :size="14"/>{{ selected.completed?'取消走过':'标记走过' }}</button></div><h3>沿途的每一站</h3><ol class="tw-route-stations"><li v-for="(point,index) in selected.waypoints" :key="index"><span>{{ index+1 }}</span><div><b>{{ point.name }}</b><p v-if="point.note">{{ point.note }}</p></div></li></ol><section v-if="selected.tips" class="tw-route-tips"><h3>给出发前的提醒</h3><p>{{ selected.tips }}</p></section><details class="tw-material-evidence"><summary>资料来源 · {{ selected.sourceLabel }}</summary><blockquote v-if="selected.evidence">{{ selected.evidence }}</blockquote><a v-if="safeSource(selected.sourceUrl)" :href="safeSource(selected.sourceUrl)!" target="_blank" rel="noopener noreferrer">打开原始来源 →</a></details><div class="tw-route-detail-actions"><button class="tw-button secondary" @click="exportSelected"><Download :size="14"/>导出路线</button><button class="tw-text danger" @click="deleteOpen=true;error='' "><Trash2 :size="14"/>删除收藏</button></div></div><aside class="tw-route-map"><TravelMap v-if="mapPoints.length" :points="mapPoints" :route="mapPoints.length===selected.waypoints.length"/><section v-else class="tw-route-map-empty"><Route :size="36"/><h3>这段路，还差地图上的坐标。</h3><p>途经点的文字顺序已经保存。将它们收藏为地点并补充位置后，这里会显示地图。</p><button class="tw-button secondary" @click="emit('openPlaces')">去地点收藏补充位置<ArrowRight :size="14"/></button></section><p>{{ mapPoints.length }} / {{ selected.waypoints.length }} 站匹配到同名同城的已定位收藏。<br/>路线顺序不等于导航轨迹；虚线只连结已核实点位。</p><small>收藏里的地点可编辑定位，路线随后按同名同城匹配。不会根据游记臆造坐标或步道轨迹。</small></aside></section></template>
  </section>
  <TravelModal v-if="editor" :title="editingId?'编辑收藏路线':'一条值得记下的路线'" eyebrow="YOUR ROUTE COLLECTION" wide :locked="busy" :error="error" @close="editor=null"><form @submit.prevent="persist"><div class="tw-modal-body"><RouteFields :value="editor"/></div><footer class="tw-modal-footer"><button class="tw-button secondary" type="button" :disabled="busy" @click="editor=null">取消</button><button class="tw-button primary" :disabled="busy">{{ busy?'保存中…':'保存路线' }}</button></footer></form></TravelModal>
  <TravelModal v-if="applyOpen&&selected" title="把这段路线，排进旅行。" eyebrow="ADD TO YOUR TRIP" :locked="busy" :error="error" @close="applyOpen=false"><form @submit.prevent="apply"><div class="tw-modal-body"><p class="tw-hint">按顺序追加 {{ selected.waypoints.length }} 个途经点，不删除原有安排。时间是可编辑的草稿，请核对交通和停留时长。</p><label class="tw-field">选择旅行<select v-model="tripId" required @change="chooseTrip"><option value="" disabled>选择已有日期的旅行</option><option v-for="t in trips.trips.filter(t=>t.startsOn&&t.endsOn&&/^[0-9a-f-]{36}$/i.test(t.id))" :key="t.id" :value="t.id">{{ t.name }}</option></select></label><label class="tw-field">加入哪一天<select v-model="date" required><option value="" disabled>先选择旅行</option><option v-for="d in dates" :key="d" :value="d">{{ d }}</option></select></label><div class="tw-form-grid"><label class="tw-field">开始时间<input v-model="startsAt" type="time" required/></label><label class="tw-field">每站暂定停留 · 分钟<input v-model.number="minutes" type="number" required min="1" max="480" step="1"/></label></div><p v-if="targetTrip&&date" class="tw-hint">这一天已有 {{ targetTrip.stops.filter(s=>s.dayDate===date).length }} 项安排，请留意时间重叠。资料标注的路线总耗时不会自动分配为各站停留时间。</p></div><footer class="tw-modal-footer"><button class="tw-button secondary" type="button" :disabled="busy" @click="applyOpen=false">取消</button><button class="tw-button primary" :disabled="busy||!tripId||!date">{{ busy?'加入中…':'确认追加安排' }}</button></footer></form></TravelModal>
  <TravelModal v-if="deleteOpen&&selected" title="删除这条路线收藏？" :locked="busy" :error="error" @close="deleteOpen=false"><div class="tw-modal-body"><p>将删除“{{ selected.name }}”。已经加入旅行的安排和原有地点收藏会保留。</p></div><footer class="tw-modal-footer"><button class="tw-button secondary" :disabled="busy" @click="deleteOpen=false">保留</button><button class="tw-button primary" :disabled="busy" @click="destroy">确认删除</button></footer></TravelModal>
</template>
